from pathlib import Path
import json,difflib
R=Path(__file__).resolve().parents[1]/'rtl_cases_real_scale210_independent_next'

def make(cid,module,c,b,spec,gold,weaks,tbs,family,sigs):
 d=R/cid;d.mkdir(parents=True,exist_ok=True)
 for n,x in [('correct.v',c),('buggy.v',b),('spec.md',spec+'\n'),('golden.sva',gold+'\n')]: (d/n).write_text(x,encoding='utf8')
 (d/'mutation.diff').write_text(''.join(difflib.unified_diff(c.splitlines(1),b.splitlines(1),fromfile='correct.v',tofile='buggy.v')),encoding='utf8')
 arr=[]
 for i,(k,p,a,why) in enumerate(weaks,1): arr.append({'id':f'W{i}_{k}','weakness_class':k,'property':p,'antecedent':a,'antecedent_nonempty':a is not None,'expected_weakness':why,'validation_status':'pending','catches_bug':None,'nonvacuity_verified':False})
 (d/'weak_assertions.json').write_text(json.dumps({'schema_version':'weak-assertions-v1','case_id':cid,'parent_bug_id':cid,'source_project':'common_cells','admission_rule':'At least two non-vacuous weak assertions must miss the RTL bug.','overall_validation_status':'pending','assertions':arr},indent=2)+'\n',encoding='utf8')
 (d/'weak_assertions.sva').write_text('\n'.join(f'// {k}\nassert property (@(posedge clk_i) disable iff (!rst_ni) ({p}));' for k,p,a,w in weaks)+'\n',encoding='utf8')
 for n,x in zip(['tb.v','tb_holdout.v','tb_decoy.v'],tbs):(d/n).write_text(x,encoding='utf8')
 meta={'name':cid,'parent_bug_id':cid,'source_project':'common_cells','source_url':'https://github.com/pulp-platform/common_cells.git','source_commit':'local-vendored-snapshot','source_module':module,'source_files':[f'external/common_cells/src/{module}.sv'],'bug_class':'combination_protocol','bug_family':family,'mutation_kind':'actual_rtl_logic_change','relevant_signals':sigs,'temporal_type':'cross-cycle ready-valid/state protocol','status':'candidate_pending_semantic_and_hardness_validation','golden_sva':{'assertion':gold},'trace_variants':['primary','heldout','decoy'],'first_divergence':{'primary':None,'heldout':None,'decoy':None}}
 (d/'case_metadata.json').write_text(json.dumps(meta,indent=2)+'\n',encoding='utf8')

def tb(decl,inst,mon,args,body):return f'''`timescale 1ns/1ps\nmodule tb; reg clk_i=0,rst_ni=0,clr_i=0;always #5 clk_i=~clk_i;{decl}\n{inst}\ninitial begin if($test$plusargs("VCD"))begin $dumpfile("wave.vcd");$dumpvars(0,tb);end $monitor("T=%0t {mon}",$time,{args});#12 rst_ni=1;{body}#40 $finish;end endmodule\n'''

ring='''module cc_ring_buffer #(parameter Depth=4,parameter Width=8)(input clk_i,rst_ni,clr_i,input wvalid_i,output wready_o,input [Width-1:0] wdata_i,input advance_i,input [2:0] step_i,output [2:0] wptr_o,rptr_o,output empty_o,full_o);reg [2:0] wp,rp;reg [Width-1:0] mem[0:Depth-1];wire wa=wvalid_i&&wready_o;assign empty_o=wp==rp;assign full_o=(wp[1:0]==rp[1:0])&&(wp[2]!=rp[2]);assign wready_o=!full_o;assign wptr_o=wp;assign rptr_o=rp;always @(posedge clk_i or negedge rst_ni)if(!rst_ni)begin wp<=0;rp<=0;end else if(clr_i)begin wp<=0;rp<=0;end else begin if(wa)begin mem[wp[1:0]]<=wdata_i;wp<=wp+1;end if(advance_i)rp<=rp+step_i;end endmodule\n'''
ringb=ring.replace('if(advance_i)rp<=rp+step_i;','else if(advance_i)rp<=rp+step_i; // MUTATION: write suppresses simultaneous advance')
def rtb(body):return tb('reg wvalid_i=0,advance_i=0;reg[7:0]wdata_i=0;reg[2:0]step_i=1;wire wready_o,empty_o,full_o;wire[2:0]wptr_o,rptr_o;','cc_ring_buffer dut(.*);','wp=%0d rp=%0d wv=%b adv=%b','wptr_o,rptr_o,wvalid_i,advance_i',body)
w=[('single_cycle_implication','wvalid_i && wready_o |-> !full_o','wvalid_i && wready_o','Only checks acceptance cycle.'),('final_output_only','!$isunknown(wptr_o)',"1'b1",'Known output does not establish pointer concurrency.'),('delay_removed','advance_i |-> rptr_o==rptr_o','advance_i','Drops next-cycle update.'),('antecedent_removed','wready_o || full_o',None,'No collision trigger.'),('simple_invariant','empty_o |-> !full_o','empty_o','Status invariant misses collision.')]
make('case466_cc_ring_buffer_write_advance_collision','cc_ring_buffer',ring,ringb,'Accepted write and independent advance in the same cycle must update both pointers.','assert property (@(posedge clk_i) disable iff (!rst_ni) (wvalid_i&&wready_o&&advance_i) |=> (wptr_o==$past(wptr_o)+1 && rptr_o==$past(rptr_o)+$past(step_i)));',w,[rtb('#13 wvalid_i=1;wdata_i=8\'h11;#10 wvalid_i=0;#10 wvalid_i=1;advance_i=1;wdata_i=8\'h22;#10 wvalid_i=0;advance_i=0;'),rtb('#13 wvalid_i=1;wdata_i=1;#30 wvalid_i=0;advance_i=1;step_i=2;#10 wvalid_i=1;advance_i=1;wdata_i=9;#10 wvalid_i=0;advance_i=0;'),rtb('#13 wvalid_i=1;#20 wvalid_i=0;#20 advance_i=1;#10 wvalid_i=1;advance_i=1;step_i=1;#10 wvalid_i=0;advance_i=0;')],'independent_updates_wrongly_exclusive',['clk_i','rst_ni','wvalid_i','wready_o','advance_i','step_i','wptr_o','rptr_o'])

loss='''module cc_lossy_valid_to_stream #(parameter Width=8)(input clk_i,rst_ni,clr_i,input valid_i,input[Width-1:0]data_i,output valid_o,input ready_i,output[Width-1:0]data_o,output busy_o);reg rp,wp;reg[1:0]cnt;reg[Width-1:0]mem[0:1];assign valid_o=(cnt!=0)||valid_i;assign data_o=(cnt==0&&valid_i)?data_i:mem[rp];assign busy_o=cnt!=0;always @(posedge clk_i or negedge rst_ni)if(!rst_ni)begin rp<=0;wp<=0;cnt<=0;end else if(clr_i)begin rp<=0;wp<=0;cnt<=0;end else begin if(valid_i&&(cnt!=0||!ready_i))begin if(cnt==2&&!ready_i)mem[wp-1'b1]<=data_i;else begin mem[wp]<=data_i;wp<=wp+1;end end if(valid_i&&!(valid_o&&ready_i)&&cnt!=2)cnt<=cnt+1;else if(!valid_i&&valid_o&&ready_i)begin cnt<=cnt-1;rp<=rp+1;end end endmodule\n'''
lossb=loss.replace('mem[wp-1\'b1]<=data_i','mem[wp]<=data_i /* MUTATION: overwrite wrong slot */')
def ltb(body):return tb('reg valid_i=0,ready_i=0;reg[7:0]data_i=0;wire valid_o,busy_o;wire[7:0]data_o;','cc_lossy_valid_to_stream dut(.*);','vi=%b ri=%b vo=%b do=%h busy=%b','valid_i,ready_i,valid_o,data_o,busy_o',body)
wl=[('single_cycle_implication','valid_i |-> valid_o','valid_i','Validity alone ignores queued order.'),('final_output_only','valid_o |-> !$isunknown(data_o)','valid_o','Knownness misses wrong item.'),('delay_removed','valid_i && ready_i |-> data_o==data_i','valid_i && ready_i','Only fall-through case.'),('antecedent_removed','busy_o || !busy_o',None,'No overwrite trigger.'),('simple_invariant','busy_o |-> valid_o','busy_o','Occupancy relation misses contents.')]
make('case467_cc_lossy_stream_overwrite_wrong_slot','cc_lossy_valid_to_stream',loss,lossb,'When full and stalled, a new input overwrites the newest pending item; draining yields the oldest item followed by the latest input.','assert property (@(posedge clk_i) disable iff (!rst_ni) (dut.cnt==2 && valid_i && !ready_i) |=> dut.mem[$past(dut.wp)-1\'b1]==$past(data_i));',wl,[ltb('#13 valid_i=1;data_i=8\'hA1;#10 data_i=8\'hB2;#10 data_i=8\'hC3;#10 valid_i=0;ready_i=1;#30 ready_i=0;'),ltb('#13 valid_i=1;data_i=8\'h14;#10 data_i=8\'h25;#10 data_i=8\'h36;#10 data_i=8\'h47;#10 valid_i=0;ready_i=1;#30 ready_i=0;'),ltb('#13 valid_i=1;data_i=8\'h81;#20 valid_i=0;#10 valid_i=1;data_i=8\'hE5;#10 valid_i=0;ready_i=1;#30 ready_i=0;')],'full_queue_latest_item_overwrite',['clk_i','rst_ni','valid_i','ready_i','data_i','valid_o','data_o','busy_o'])

spill='''module cc_spill_register #(parameter Width=8)(input clk_i,rst_ni,clr_i,input valid_i,output ready_o,input[Width-1:0]data_i,output valid_o,input ready_i,output[Width-1:0]data_o);reg af,bf;reg[Width-1:0]ad,bd;wire adrain=af&&!bf;wire afill=valid_i&&ready_o;wire bfill=adrain&&!ready_i;assign ready_o=!af||!bf;assign valid_o=af||bf;assign data_o=bf?bd:ad;always @(posedge clk_i or negedge rst_ni)if(!rst_ni)begin af<=0;bf<=0;end else if(clr_i)begin af<=0;bf<=0;end else begin if(afill)begin af<=1;ad<=data_i;end else if(adrain)af<=0;if(bfill)begin bf<=1;bd<=ad;end else if(bf&&ready_i)bf<=0;end endmodule\n'''
spillb=spill.replace('wire bfill=adrain&&!ready_i;','wire bfill=adrain; // MUTATION: caches drained item even when consumed')
def ptb(body):return tb('reg valid_i=0,ready_i=0;reg[7:0]data_i=0;wire ready_o,valid_o;wire[7:0]data_o;','cc_spill_register dut(.*);','vi=%b ri=%b vo=%b do=%h','valid_i,ready_i,valid_o,data_o',body)
wp=[('single_cycle_implication','valid_i && ready_o |-> valid_o || !valid_o','valid_i && ready_o','No ordered future check.'),('final_output_only','valid_o |-> !$isunknown(data_o)','valid_o','Known output may be duplicated.'),('delay_removed','ready_i |-> ready_o || valid_o','ready_i','Local handshake only.'),('antecedent_removed','ready_o || !ready_o',None,'Drops drain/refill collision.'),('simple_invariant','valid_o == (dut.af||dut.bf)',None,'Internal consistency survives mutation.')]
make('case468_cc_spill_register_drain_refill_duplicate','cc_spill_register',spill,spillb,'A buffered item consumed while the internal stage drains must not be copied into the backup stage and emitted twice.','assert property (@(posedge clk_i) disable iff (!rst_ni) (dut.af && !dut.bf && ready_i) |=> !dut.bf);',wp,[ptb('#13 valid_i=1;data_i=8\'h31;#10 valid_i=0;ready_i=1;#20 ready_i=0;'),ptb('#13 valid_i=1;data_i=8\'h42;#10 valid_i=0;#10 ready_i=1;#10 valid_i=1;data_i=8\'h53;#10 valid_i=0;#20 ready_i=0;'),ptb('#13 valid_i=1;data_i=8\'hA0;#10 valid_i=0;#20 ready_i=1;#20 ready_i=0;')],'simultaneous_internal_drain_and_output_consume',['clk_i','rst_ni','valid_i','ready_o','ready_i','valid_o','data_o'])

regv='''module cc_stream_register #(parameter Width=8)(input clk_i,rst_ni,clr_i,input valid_i,output ready_o,input[Width-1:0]data_i,output reg valid_o,input ready_i,output reg[Width-1:0]data_o);wire ena=valid_i&&ready_o;assign ready_o=ready_i||!valid_o;always @(posedge clk_i or negedge rst_ni)if(!rst_ni)begin valid_o<=0;data_o<=0;end else if(clr_i)valid_o<=0;else begin if(ready_o)valid_o<=valid_i;if(ena)data_o<=data_i;end endmodule\n'''
regb=regv.replace('wire ena=valid_i&&ready_o;','wire ena=valid_i; // MUTATION: stalled output can be overwritten')
def vtb(body):return tb('reg valid_i=0,ready_i=0;reg[7:0]data_i=0;wire ready_o,valid_o;wire[7:0]data_o;','cc_stream_register dut(.*);','vi=%b ro=%b ri=%b vo=%b do=%h','valid_i,ready_o,ready_i,valid_o,data_o',body)
wv=[('single_cycle_implication','valid_i && ready_o |=> valid_o','valid_i && ready_o','Accepted valid still works.'),('final_output_only','valid_o |-> !$isunknown(data_o)','valid_o','Knownness misses overwrite.'),('delay_removed','valid_i |-> ready_o || !ready_o','valid_i','No stability duration.'),('antecedent_removed','valid_o || !valid_o',None,'Drops stall trigger.'),('simple_invariant','ready_o == (ready_i || !valid_o)',None,'Ready equation is unchanged.')]
make('case469_cc_stream_register_stall_overwrite','cc_stream_register',regv,regb,'While valid is asserted and ready is low, output data remains stable until consumed.','assert property (@(posedge clk_i) disable iff (!rst_ni) (valid_o && !ready_i) |=> (valid_o && data_o==$past(data_o)));',wv,[vtb('#13 valid_i=1;data_i=8\'h61;#10 data_i=8\'h72;#10 valid_i=0;#10 ready_i=1;#10 ready_i=0;'),vtb('#13 valid_i=1;data_i=8\'h19;#10 data_i=8\'h2A;#10 data_i=8\'h3B;#10 valid_i=0;ready_i=1;#10 ready_i=0;'),vtb('#13 valid_i=1;data_i=8\'hC1;#10 valid_i=0;#20 valid_i=1;data_i=8\'hD2;#10 valid_i=0;ready_i=1;#10 ready_i=0;')],'backpressure_payload_stability',['clk_i','rst_ni','valid_i','ready_o','data_i','valid_o','ready_i','data_o'])

join='''module cc_stream_join_dynamic #(parameter NumInp=4)(input clk_i,rst_ni,clr_i,input[NumInp-1:0]inp_valid_i,output[NumInp-1:0]inp_ready_o,input[NumInp-1:0]sel_i,output oup_valid_o,input oup_ready_i);assign oup_valid_o=&(inp_valid_i|~sel_i)&&|sel_i;genvar i;generate for(i=0;i<NumInp;i=i+1)begin assign inp_ready_o[i]=oup_valid_o&&oup_ready_i&&sel_i[i];end endgenerate endmodule\n'''
joinb=join.replace('sel_i[i];end','sel_i[(i+1)%NumInp]; // MUTATION: ready mask rotated\nend')
def jtb(body):return tb('reg[3:0]inp_valid_i=0,sel_i=0;reg oup_ready_i=0;wire[3:0]inp_ready_o;wire oup_valid_o;','cc_stream_join_dynamic dut(.*);','iv=%b sel=%b ov=%b ir=%b','inp_valid_i,sel_i,oup_valid_o,inp_ready_o',body)
wj=[('single_cycle_implication','oup_valid_o |-> |inp_valid_i','oup_valid_o','Does not check ready destination.'),('final_output_only','!$isunknown(inp_ready_o)',"1'b1",'Known mask may be wrong.'),('delay_removed','oup_ready_i |-> oup_ready_i','oup_ready_i','No selection relation.'),('antecedent_removed','|sel_i |-> |sel_i',None,'Drops successful join trigger.'),('simple_invariant','|inp_ready_o |-> oup_ready_i','|inp_ready_o','Rotated ready still implies output ready.')]
make('case470_cc_stream_join_dynamic_rotated_ready','cc_stream_join_dynamic',join,joinb,'On a successful selected join, ready is asserted on exactly the selected input lanes and no others.','assert property (@(posedge clk_i) disable iff (!rst_ni) (oup_valid_o && oup_ready_i) |-> inp_ready_o==sel_i);',wj,[jtb('#13 sel_i=4\'b0101;inp_valid_i=4\'b0101;oup_ready_i=1;#20 oup_ready_i=0;'),jtb('#13 sel_i=4\'b1010;inp_valid_i=4\'b1110;#10 oup_ready_i=1;#20 oup_ready_i=0;'),jtb('#13 sel_i=4\'b0011;inp_valid_i=4\'b1011;oup_ready_i=1;#10 sel_i=4\'b1100;inp_valid_i=4\'b1101;#20 oup_ready_i=0;')],'selected_lane_ready_routing',['clk_i','rst_ni','inp_valid_i','inp_ready_o','sel_i','oup_valid_o','oup_ready_i'])
